message.content:
{
  "description": "The creature is a large quadrupedal animal with the overall body shape, dense shaggy brown fur, and head of a bear, standing in profile facing right. Its body is covered in thick brown fur that is lighter on the muzzle and darker on the legs. Integrated into the fur are glossy, dark reddish-brown, hard beetle-like structures and two large translucent membranous wings. A long segmented glossy tail extends from the rear. Rows of narrow dark slits are visible in the fur on the side and hip.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with dense brown fur, lighter tan fur on the muzzle, a large black nose, small brown eyes, and a slightly open mouth, facing right in profile at the front of the body"
    ,
      "where": "at the front of the body on top of the neck"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur with slightly darker edges",
      "where": "on top of the head, one behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout, heavily furred legs covered in long shaggy brown fur",
      "where": "supporting the body, two front legs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large paws with long curved light-tan claws and dark pads, the tops covered in fur",
      "where": "at the ends of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, tapering, segmented tail made of glossy dark reddish-brown overlapping hard plates, ending in a small two-pronged fork",
      "where": "extending from the rear of the body at the rump"
    },
    {
      "part": "wings",
      "looks_like": "two large translucent membranous wings with prominent dark brown veining and light tan membrane, slightly crinkled and reflective",
      "where": "one protruding from the left mid-side over the back and one protruding from the right chest/shoulder area"
    },
    {
      "part": "shell",
      "looks_like": "five glossy, smooth, oval, dark reddish-brown hard elytra (beetle wing covers) with a central seam and reflective highlights",
      "where": "clustered on the neck, shoulder and left side of the body, surrounding the base of the left wing"
    },
    {
      "part": "plates",
      "looks_like": "overlapping glossy dark reddish-brown hard plates forming segmented armor",
      "where": "forming the entire length of the tail"
    },
    {
      "part": "gills",
      "looks_like": "rows of narrow vertical dark slit-like openings set into the fur, five slits on the mid-flank and about ten slits in a curved diagonal row on the hip",
      "where": "on the left side of the body in the fur on the flank and on the upper hind leg/hip"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
